def encode(message):
    vowels = 'aeiouAEIOU'
    result = []
    for char in message:
        # Swap case
        if char.isupper():
            char = char.lower()
        elif char.islower():
            char = char.upper()
        # Replace vowels with letter 2 places ahead
        if char in vowels:
            char = chr(ord(char) + 2)
        result.append(char)
    return ''.join(result)

